<div class="page-title"><div><em>LENDING OPERATIONS</em><h1>Loan management</h1><p>Review applications and monitor active lending.</p></div><button class="btn">+ New loan</button></div><section class="panel"><div class="data-table loan-table"><div class="tr th"><span>Borrower</span><span>Reference</span><span>Principal</span><span>Outstanding</span><span>Rate</span><span>Status</span></div><?php foreach($loans as $l):?><div class="tr"><span class="name"><i><?=initials($l['first_name'].' '.$l['last_name'])?></i><b><?=html_escape($l['first_name'].' '.$l['last_name'])?></b></span><strong><?=$l['reference']?></strong><span><?=money($l['principal'])?></span><strong><?=money($l['outstanding_balance'])?></strong><span><?=$l['interest_rate']?>%</span><span class="<?=status_class($l['status'])?>"><?=ucfirst($l['status'])?></span></div><?php endforeach?></div></section>
